#!/usr/bin/env node
// Merge scripts/i18n/<locale>.json into the two client bundles.
//
// One source of truth for both plugins: the user and worker panels show the
// same product vocabulary (Wallet, campaign, claim, ...), and a string that is
// translated once should not drift between them. The generated file is
// committed so a build never depends on the translation step.

import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const dir = join(root, 'scripts/i18n')
const en = JSON.parse(readFileSync(join(dir, 'en.json'), 'utf8'))
const locales = ['zh', 'en', 'ja', 'ko', 'es', 'fr', 'de', 'ru', 'pt']
const messages = {}

for (const locale of locales) {
  const file = join(dir, `${locale}.json`)
  let dict
  try {
    dict = JSON.parse(readFileSync(file, 'utf8'))
  } catch {
    if (locale !== 'en') console.warn(`missing ${file}; falling back to English for ${locale}`)
    dict = en
  }
  if (locale === 'en') dict = en
  const missing = Object.keys(en).filter(key => !(key in dict))
  if (missing.length > 0) {
    console.warn(`${locale}: ${missing.length} missing key(s), English fallback at runtime`)
    for (const key of missing) dict[key] = en[key]
  }
  messages[locale] = Object.fromEntries(Object.keys(en).map(key => [key, dict[key]]))
}

const labels = {
  auto: 'Follow DSH',
  zh: '中文',
  en: 'English',
  ja: '日本語',
  ko: '한국어',
  es: 'Español',
  fr: 'Français',
  de: 'Deutsch',
  ru: 'Русский',
  pt: 'Português',
}

const body = `// Generated by scripts/gen-plugin-locales.mjs from scripts/i18n/*.json.
// Edit the JSON, run the script, commit both.

export const MESSAGES = ${JSON.stringify(messages, null, 2)} as const

export const LOCALE_LABELS: Record<string, string> = ${JSON.stringify(labels, null, 2)}

export type MessageLocale = keyof typeof MESSAGES
`

for (const pkg of ['user', 'worker']) {
  const out = join(root, 'packages', pkg, 'src/client/locales.ts')
  writeFileSync(out, body)
  console.log(`wrote ${out}`)
}
